import {useCallback, useEffect, useMemo, useRef, useState} from 'react';

import type {CancellablePromise} from '@gravity-ui/sdk';
import debounce from 'lodash/debounce';
import {useUnmount} from 'react-use';

export function useAutocomplete<T>(
    getData: (search: string) => CancellablePromise<T>,
    searchDelay = 300,
    useBoostedValues = false,
) {
    const [filteredItems, setFilteredItems] = useState<T | undefined>();
    const [isLoading, setIsLoading] = useState(false);
    const [searchText, setSearchText] = useState('');
    const searchRequestRef = useRef<CancellablePromise<T[]>>();

    const searchDebounced = useMemo(
        () =>
            debounce((search: string) => {
                setSearchText(search);
                searchRequestRef.current = getData(search)
                    .then((items) => {
                        setFilteredItems(items);
                    })
                    .catch((error) => {
                        if (!error.isCancelled) {
                            console.error(error);
                        }
                    })
                    .finally(() => {
                        setIsLoading(false);
                    }) as unknown as CancellablePromise<T[]>;
            }, searchDelay),
        [getData, searchDelay],
    );

    useEffect(() => {
        if (useBoostedValues) {
            setIsLoading(true);
            searchDebounced('');
        }
    }, [useBoostedValues, searchDebounced]);

    useUnmount(() => {
        if (searchRequestRef?.current && 'cancel' in searchRequestRef.current) {
            searchRequestRef.current.cancel();
        }

        searchDebounced?.cancel();
    });

    const resetFilteredItems = useCallback(() => {
        if (searchRequestRef.current && 'cancel' in searchRequestRef.current) {
            searchRequestRef.current.cancel();
        }

        searchDebounced.cancel();
        setFilteredItems(undefined);
        setIsLoading(false);
    }, [searchDebounced]);

    const handleFilterChange = useCallback(
        (search: string, force?: boolean) => {
            if (searchRequestRef.current && 'cancel' in searchRequestRef.current) {
                searchRequestRef.current.cancel();
            }

            searchDebounced.cancel();

            if (!search && !useBoostedValues && !force) {
                setSearchText('');
                resetFilteredItems();

                return;
            }

            setIsLoading(true);
            searchDebounced(search);
        },
        [resetFilteredItems, searchDebounced, useBoostedValues],
    );

    const emitFilterChange = useCallback(() => {
        handleFilterChange(searchText, true);
    }, [handleFilterChange, searchText]);

    return {
        filteredItems,
        resetFilteredItems,
        handleFilterChange,
        isLoading,
        searchText,
        emitFilterChange,
    };
}
